import useStore from '@/AppBuilder/_stores/store';
import { resolveEffectiveRevision } from '@/AppBuilder/Widgets/libraryComponentRevision';

// F5+: the pin IS the selection now — VersionPicker writes it immediately whether the
// chosen entry is a revision ('v3') or a dev bundle ('dev:{userId}'); there is no
// separate session-local preview layer anymore.
export const useEffectiveLibraryRevision = (correlationId: string | undefined): string | undefined =>
  useStore((state: any) => resolveEffectiveRevision(state.globalSettings?.customComponentLibraries, correlationId));
import { useEffect } from 'react';
import { useCustomComponentLibrariesStore } from '@/_stores/customComponentLibrariesStore';
import { buildManifestCacheKey } from '@/_helpers/customComponentLibrariesStoreUtils';

import type { LibraryManifest } from '@/AppBuilder/types/libraryComponent.types';

// Shared reactive manifest cache — one fetch per (libraryId, revision) no matter how
// many components/panels need it. Reads real Zustand state, so every consumer re-renders
// once an in-flight fetch resolves.
export const useLibraryManifest = (libraryId?: string, revision?: string): LibraryManifest | null => {
  // const currentMode = useStore((state) => state.modeStore?.modules?.canvas?.currentMode ?? 'view');
  // const hasCustomComponentLibrariesAccess = useStore(
  //   (state) => state.license?.featureAccess?.customComponentLibraries === true
  // );

  // Not part of the cache key — only here to re-trigger the fetch after a live push
  // invalidates the manifest.
  const devNonce = useCustomComponentLibrariesStore((state: any) =>
    revision?.startsWith?.('dev:') ? state.devBundleUpdatedAt?.[libraryId ?? ''] : undefined
  );
  const key = libraryId && revision ? buildManifestCacheKey(libraryId, revision) : undefined;
  const manifest = useCustomComponentLibrariesStore((state: any) => (key ? state.manifests[key] : undefined));

  useEffect(() => {
    if (!libraryId || !revision) return;
    useCustomComponentLibrariesStore.getState().fetchManifest(libraryId, revision);
  }, [libraryId, revision, devNonce]);

  return manifest ?? null;
};
import { buildManifestCacheKey } from '@/_helpers/customComponentLibrariesStoreUtils';
import type { LibraryManifest, ManifestAction } from '@/AppBuilder/types/libraryComponent.types';

export type Pin = string | { revisionId?: string; revision_id?: string } | undefined | null;

interface ResolvedActionParam {
  handle: string;
  displayName: string;
  defaultValue?: unknown;
  type?: string;
  options?: unknown;
}

export interface ResolvedAction {
  handle: string;
  displayName: string;
  params: ResolvedActionParam[];
}

export interface ComponentIdentity {
  libraryId?: string;
  correlationId?: string;
  componentName?: string;
}

export interface ComponentDefinitionLike {
  component?: {
    definition?: {
      properties?: Record<string, { value?: string }>;
    };
  };
}

// Every call site passes a correlationId (pins are keyed by dashless correlationId,
// never by libraryId — see resolveEffectiveRevision below), so this takes a generic
// id rather than implying it's library-specific.
export const dashlessId = (id: string | undefined): string | undefined => id?.replace(/-/g, '');

export const normalizePin = (pin: Pin): string | undefined =>
  typeof pin === 'string' ? pin : (pin?.revisionId ?? pin?.revision_id);

// F5+: the pin IS the selection now — VersionPicker writes it immediately whether the
// chosen entry is a revision ('v3') or a dev bundle ('dev:{userId}'); there is no
// separate session-local preview layer anymore (see invariant #14, HANDOFF-NISHIDH.md).
// Keyed by the library's correlationId (stable across workspaces), not its workspace-scoped
// id — so a pin keeps resolving after the app is exported/imported into another workspace.
export const resolveEffectiveRevision = (
  pins: Record<string, Pin> | undefined,
  correlationId: string | undefined
): string | undefined => normalizePin(pins?.[dashlessId(correlationId) ?? ''] ?? pins?.[correlationId ?? '']);

// Reads a LibraryComponent instance's identity off its definition.properties — the only
// place it lives (never rendered as editable inspector fields). Shared by the Inspector
// panel and EventManager, which both need to resolve a manifest for an arbitrary
// component definition, not just the one currently mounted on the canvas.
export const getLibraryComponentIdentity = (component: ComponentDefinitionLike): ComponentIdentity => {
  const definitionProps = component.component?.definition?.properties ?? {};
  return {
    libraryId: definitionProps.libraryId?.value,
    correlationId: definitionProps.correlationId?.value,
    componentName: definitionProps.componentName?.value,
  };
};

// The Switch element labels options by `displayName`; select and the manifest use `name`.
const toSwitchOption = ({ name, value }: { name: string; value: string }) => ({ displayName: name, value });

// EventManager's action picker/param UI expects a normalized `handle` (not the manifest's
// `name`) on both the action and each param — this is the one place that shape gets
// produced, shared by anyone reading actions off a resolved manifest.
export const resolveManifestActions = (
  manifest: LibraryManifest | null | undefined,
  componentName: string | undefined
): ResolvedAction[] => {
  const actions: ManifestAction[] = (componentName && manifest?.components?.[componentName]?.actions) || [];
  return actions.map((a) => ({
    handle: a.name,
    displayName: a.displayName ?? a.name,
    params: (a.params ?? []).map((p) => ({
      handle: p.handle,
      displayName: p.displayName ?? p.handle,
      defaultValue: p.defaultValue,
      ...(p.type ? { type: p.type } : {}),
      ...(p.options ? { options: p.type === 'switch' ? p.options.map(toSwitchOption) : p.options } : {}),
    })),
  }));
};

// Dynamic (manifest) actions are appended after static ones (e.g. setVisibility), never
// replacing them.
export const mergeStaticAndDynamicActions = (
  staticActions: ResolvedAction[],
  dynamicActions: ResolvedAction[]
): ResolvedAction[] => [...staticActions, ...dynamicActions];

// Resolves a LibraryComponent's actions from the shared manifest cache for an arbitrary
// component definition — e.g. EventManager, which needs this for whatever component an
// event targets, not just the one it's currently rendering. Read-only: the manifest must
// already be in `manifests`; this returns [] rather than triggering a fetch itself.
export const resolveLibraryComponentActions = (
  componentDef: ComponentDefinitionLike,
  manifests: Record<string, LibraryManifest>,
  pins: Record<string, Pin> | undefined
): ResolvedAction[] => {
  const { libraryId, correlationId, componentName } = getLibraryComponentIdentity(componentDef);
  const revision = resolveEffectiveRevision(pins, correlationId);
  if (!libraryId || !revision) return [];
  const key = buildManifestCacheKey(libraryId, revision);
  return resolveManifestActions(manifests[key], componentName);
};
// Pure helpers for customComponentLibrariesStore - no store/SSE/fetch access here, so
// these are unit-testable without mocking any of that.

import config from 'config';
import { dashlessId } from '@/AppBuilder/Widgets/libraryComponentRevision';
import type { CustomComponentLibrary } from '@/_services/customComponentLibraries.service';

// Builds bundle/css/manifest URLs for either a published revision ('v2') or a
// dev slot ('dev:{userId}' → the per-developer no-store endpoint). Lives in this leaf
// helpers file (rather than libraryComponentRevision.ts) so customComponentLibrariesStore
// can import it without a store <-> libraryComponentRevision import cycle.
export const libraryFileUrl = (libraryId: string, revision: string | undefined, file: string): string =>
  revision?.startsWith?.('dev:')
    ? `${config.apiUrl}/custom-component-libraries/${libraryId}/dev/${revision.slice(4)}/files/${file}`
    : `${config.apiUrl}/custom-component-libraries/${libraryId}/revisions/${revision}/files/${file}`;

// Stable key by (libraryId, revision) — no devNonce. Dev-slot staleness is handled by
// explicitly invalidating this key (see customComponentLibrariesStore's invalidateManifest)
// instead of growing the key space on every push.
export const buildManifestCacheKey = (libraryId: string, revision: string): string => `${libraryId}@${revision}`;

// devPinKeys: { [dashlessCorrelationId]: 'dev:{userId}' }, exactly as stored in
// globalSettings.customComponentLibraries.
type DevPinKeys = Record<string, string>;

// { libraryId: userId }
type OwnPins = Record<string, string>;

export const streamKey = (libraryId: string, userId: string): string => `${libraryId}:${userId}`;

// A user's email doesn't vary by library, so this flattens every library's devBundles
// into one userId -> email map instead of resolving it per pin/library.
export function buildDevPreviewEmailsByUserId(libraries: CustomComponentLibrary[]): Record<string, string> {
  const emailsByUserId: Record<string, string> = {};
  libraries.forEach((lib) => {
    lib.devBundles?.forEach((bundle) => {
      if (bundle.userEmail) emailsByUserId[bundle.userId] = bundle.userEmail;
    });
  });
  return emailsByUserId;
}

// Resolves devPinKeys (keyed by correlationId) against the library list, returning only
// the pins owned by currentUserId — the ones a live-reload stream can open for.
export function resolveOwnDevPins(
  libraries: CustomComponentLibrary[],
  devPinKeys: DevPinKeys,
  currentUserId: string | undefined
): OwnPins {
  const ownPins: OwnPins = {};

  libraries.forEach((lib) => {
    // Legacy pins may still be keyed by the dashed correlationId (pre dashlessId-normalization,
    // see libraryComponentRevision.ts's dashlessId) — fall back to it so those still resolve.
    const value = devPinKeys[dashlessId(lib.correlationId) ?? ''] ?? devPinKeys[lib.correlationId ?? ''];
    if (typeof value !== 'string' || !value.startsWith('dev:')) return;

    const userId = value.slice(4);
    if (userId === currentUserId) ownPins[lib.id] = userId;
  });

  return ownPins;
}

// Given the currently-open stream keys and the pins that should be streaming for this
// viewer, returns which keys to close and which (libraryId, userId) pairs to open.
export function diffStreamKeys(
  activeKeys: string[],
  ownPins: OwnPins
): { toClose: string[]; toOpen: [string, string][] } {
  const wantedKeys = new Set(Object.entries(ownPins).map(([libraryId, userId]) => streamKey(libraryId, userId)));

  const toClose = activeKeys.filter((key) => !wantedKeys.has(key));
  const toOpen = Object.entries(ownPins).filter(
    ([libraryId, userId]) => !activeKeys.includes(streamKey(libraryId, userId))
  );

  return { toClose, toOpen };
}
import config from 'config';
import { authHeader, handleResponse } from '@/_helpers';
import { fetchEventSource, type EventSourceMessage } from '@microsoft/fetch-event-source';
import type { LibraryManifest } from '@/AppBuilder/types/libraryComponent.types';

interface StreamDevBundleUpdatesOptions {
  onMessage?: (event: EventSourceMessage) => void;
  onError?: (error: unknown) => void;
}

export interface CustomComponentLibraryRevision {
  id: string;
  version: string;
  createdAt?: string;
}

export interface CustomComponentLibraryDevBundle {
  userId: string;
  userEmail?: string;
}

export interface CustomComponentLibrary {
  id: string;
  name: string;
  correlationId?: string;
  revisions: CustomComponentLibraryRevision[];
  devBundles?: CustomComponentLibraryDevBundle[];
  manifest?: LibraryManifest; // the latest revision's manifest, embedded so callers can skip a fetch for the common case
}

function list(): Promise<CustomComponentLibrary[]> {
  const requestOptions = { method: 'GET', headers: authHeader(), credentials: 'include' as const };
  return fetch(`${config.apiUrl}/custom-component-libraries`, requestOptions).then(handleResponse);
}

function deleteLibrary(id: string) {
  const requestOptions = { method: 'DELETE', headers: authHeader(), credentials: 'include' as const };
  return fetch(`${config.apiUrl}/custom-component-libraries/${id}`, requestOptions).then(handleResponse);
}

// One SSE connection per (libraryId, userId); caller aborts it via the returned controller.
async function streamDevBundleUpdates(
  libraryId: string,
  userId: string,
  { onMessage, onError = () => {} }: StreamDevBundleUpdatesOptions = {}
) {
  const controller = new AbortController();

  fetchEventSource(`${config.apiUrl}/custom-component-libraries/${libraryId}/dev/${userId}/stream`, {
    method: 'GET',
    headers: authHeader(),
    credentials: 'include',
    signal: controller.signal,
    onmessage: (event) => {
      if (event.event === 'dev-bundle-updated' && onMessage) onMessage(event);
    },
    onerror: (error) => {
      if (controller.signal.aborted) {
        throw error; // stops fetchEventSource from retrying
      }
      onError(error);
    },
  }).catch((error) => {
    if (!controller.signal.aborted) onError(error);
  });

  return controller;
}

export const customComponentLibrariesService = {
  list,
  deleteLibrary,
  streamDevBundleUpdates,
};
import { create, zustandDevTools } from './utils';
import {
  customComponentLibrariesService,
  type CustomComponentLibrary,
} from '@/_services/customComponentLibraries.service';
import { authenticationService } from '@/_services/authentication.service';
import {
  streamKey,
  resolveOwnDevPins,
  buildDevPreviewEmailsByUserId,
  diffStreamKeys,
  libraryFileUrl,
  buildManifestCacheKey,
} from '@/_helpers/customComponentLibrariesStoreUtils';
import type { LibraryManifest } from '@/AppBuilder/types/libraryComponent.types';

interface CustomComponentLibrariesState {
  libraries: CustomComponentLibrary[] | null; // null = not yet fetched
  loadFailed: boolean;
  devPreviewEmailsByUserId: Record<string, string>; // { [userId]: email } — feeds the canvas "dev: email" badge
  devBundleUpdatedAt: Record<string, number>; // { [libraryId]: number } — nonce bumped on each live-reload push
  manifests: Record<string, LibraryManifest>; // keyed by buildManifestCacheKey(libraryId, revision)
  fetchLibraries: (options?: { force?: boolean }) => Promise<CustomComponentLibrary[]>;
  invalidate: () => void;
  syncDevPinStreams: (devPinKeys: Record<string, string>) => void;
  fetchManifest: (libraryId: string, revision: string) => Promise<void>;
  invalidateManifest: (libraryId: string, revision: string) => void;
  resetAll: () => void;
}

// Module-scoped, not zustand state, so devtools/persist never touch it — dev bundle bytes
// must never persist into app state, only the pin string does (invariant #14, HANDOFF-NISHIDH.md).
const activeStreams = new Map<string, AbortController | null>(); // `${libraryId}:${userId}` -> AbortController

// Dedupes concurrent fetchLibraries() calls (e.g. the RightSideBar tab and the dev-pin
// sync effect both running around the same time) into a single request.
let inFlightFetch: Promise<CustomComponentLibrary[]> | null = null;

// Dedupes concurrent fetchManifest() calls for the same cache key (e.g. the widget
// runtime and the Inspector both mounting for the same instance at once).
const manifestInFlight = new Map<string, Promise<void>>();

// Every library list entry already carries its latest revision's manifest — seed the
// cache with it for free so useLibraryManifest never re-fetches what's already in hand.
function seedLatestManifests(libraries: CustomComponentLibrary[]): Record<string, LibraryManifest> {
  const seeded: Record<string, LibraryManifest> = {};
  libraries.forEach((lib) => {
    const latest = lib.revisions?.[0]?.version;
    if (latest && lib.manifest) seeded[buildManifestCacheKey(lib.id, latest)] = lib.manifest;
  });
  return seeded;
}

function closeAllStreams(): void {
  activeStreams.forEach((controller) => controller?.abort());
  activeStreams.clear();
}

function closeStream(key: string): void {
  activeStreams.get(key)?.abort();
  activeStreams.delete(key);
}

function openStream(libraryId: string, userId: string, onMessage: () => void): void {
  const key = streamKey(libraryId, userId);
  // Reserve the slot synchronously so a second reconcile pass (e.g. another
  // globalSettings write landing before this promise resolves) can't open a duplicate.
  activeStreams.set(key, null);
  customComponentLibrariesService
    .streamDevBundleUpdates(libraryId, userId, { onMessage, onError: () => {} }) // fetchEventSource auto-retries
    .then((controller: AbortController) => {
      if (activeStreams.has(key)) activeStreams.set(key, controller);
      else controller.abort(); // slot was closed before the connection finished opening
    });
}

export const useCustomComponentLibrariesStore = create(
  zustandDevTools(
    (set: any, get: any): CustomComponentLibrariesState => ({
      libraries: null,
      loadFailed: false,
      devPreviewEmailsByUserId: {},
      devBundleUpdatedAt: {},
      manifests: {},

      // Cache-first: only the first caller hits the network, same staleness contract as a
      // published version (no polling). Pass force:true to bypass the cache (Retry, delete).
      fetchLibraries: async ({ force = false } = {}) => {
        const { libraries } = get();
        if (!force && libraries !== null) return libraries;
        if (inFlightFetch) return inFlightFetch;

        inFlightFetch = customComponentLibrariesService
          .list()
          .then((result) => {
            set(
              (state: CustomComponentLibrariesState) => ({
                libraries: result,
                loadFailed: false,
                manifests: { ...state.manifests, ...seedLatestManifests(result) },
                devPreviewEmailsByUserId: {
                  ...state.devPreviewEmailsByUserId,
                  ...buildDevPreviewEmailsByUserId(result),
                },
              }),
              false,
              'fetchLibraries'
            );
            return result;
          })
          .catch((error) => {
            set({ libraries: [], loadFailed: true }, false, 'fetchLibraries:error');
            throw error;
          })
          .finally(() => {
            inFlightFetch = null;
          });

        return inFlightFetch;
      },

      // Clears just the library-list cache (not the dev-preview stream state below) — call on
      // unmount of a page that only reads the list, like the WorkspaceSettings admin page.
      invalidate: () => set({ libraries: null, loadFailed: false }, false, 'invalidate:customComponentLibraries'),

      // Opens a live-reload stream only for pins where the viewer IS the pinned developer
      // (resolveOwnDevPins). Reads the cached list rather than fetching it — caller
      // re-invokes once fetchLibraries() resolves.
      syncDevPinStreams: (devPinKeys) => {
        if (!Object.keys(devPinKeys).length) {
          closeAllStreams();
          set({ devBundleUpdatedAt: {} }, false, 'syncDevPinStreams:empty');
          return;
        }

        const { libraries } = get();
        if (!libraries) return; // not fetched yet — caller re-invokes once fetchLibraries() resolves

        const currentUserId = (authenticationService.currentSessionValue as { current_user?: { id?: string } })
          ?.current_user?.id;
        const ownPins = resolveOwnDevPins(libraries, devPinKeys, currentUserId);
        const { toClose, toOpen } = diffStreamKeys(Array.from(activeStreams.keys()), ownPins);

        toClose.forEach(closeStream);
        toOpen.forEach(([libraryId, userId]) =>
          openStream(libraryId, userId, () => {
            // A live push means this library's cached dev manifest is stale — drop it.
            const devKey = buildManifestCacheKey(libraryId, `dev:${userId}`);
            set(
              (state: CustomComponentLibrariesState) => {
                const { [devKey]: _removed, ...manifests } = state.manifests;
                return {
                  devBundleUpdatedAt: { ...state.devBundleUpdatedAt, [libraryId]: Date.now() },
                  manifests,
                };
              },
              false,
              'devBundleUpdated'
            );
          })
        );
      },

      // Fetches manifest.json for (libraryId, revision), cached by that pair — a cache hit
      // never re-fetches. Dev slots rely on invalidateManifest for freshness instead.
      // Shared by the widget runtime, Inspector, and palette so it's fetched once.
      fetchManifest: async (libraryId, revision) => {
        const key = buildManifestCacheKey(libraryId, revision);
        if (get().manifests[key]) return;
        if (manifestInFlight.has(key)) return manifestInFlight.get(key);

        const promise = fetch(libraryFileUrl(libraryId, revision, 'manifest.json'))
          .then((r) => (r.ok ? r.json() : null))
          .then((data) => {
            if (data)
              set(
                (state: CustomComponentLibrariesState) => ({ manifests: { ...state.manifests, [key]: data } }),
                false,
                'fetchManifest'
              );
          })
          .catch(() => {})
          .finally(() => manifestInFlight.delete(key));

        manifestInFlight.set(key, promise);
        return promise;
      },

      // Evicts one manifest cache entry — used for dev slots whenever content may have
      // changed (a live push, or switching a pin to dev).
      invalidateManifest: (libraryId, revision) => {
        const key = buildManifestCacheKey(libraryId, revision);
        set(
          (state: CustomComponentLibrariesState) => {
            if (!(key in state.manifests)) return state;
            const { [key]: _removed, ...manifests } = state.manifests;
            return { manifests };
          },
          false,
          'invalidateManifest'
        );
      },

      // Closes every stream and clears all dev-preview + library-list state — call on app
      // switch/unmount so connections don't leak and the next app sees a fresh library list.
      resetAll: () =>
        set(
          () => {
            closeAllStreams();
            return {
              devPreviewEmailsByUserId: {},
              devBundleUpdatedAt: {},
              libraries: null,
              loadFailed: false,
              manifests: {},
            };
          },
          false,
          'resetAll'
        ),
    }),
    { name: 'customComponentLibrariesStore' }
  )
);
